using StrataLint.Scribe;
using static StrataLint.Scribe.Combinators;

namespace Blueprint.D5.S3.Quantum.Foundation;

public sealed class OriginalRegularHeight : IScribeDocument
{
    private const string Owner = "D5/S3/Quantum/Foundation/OriginalRegularHeight.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "At each original regular anchor, every actual antipodal endpoint in every adjacent complete exclusion ball has a common positive height and attains the whole-ball maximum.",
        H("Uniform height of actual adjacent-ball endpoints"), Blocks(
            Paragraph(Text("Let V be a finite dimensional real normed space, C a closed generating pointed cone, and u strictly positive on every nonzero cone vector. K is the entire normalized base, P its entire extreme-point set, and the effects are all original linear functionals between zero and u on C. Every full exclusion has an injective affine chart by the whole closed three-ball, and equality of full exclusions implies equality of their pure labels. Fix an original pure p whose entire full confirming fiber is a singleton and whose entire zero-effect fiber is continuous along every original pure sequence tending to p. These are precisely the RegularAnchor conditions. No closedness of P, continuity of a chosen chart, joint instrument, or regularity at neighboring labels is assumed.")),
            Describe.Lean(DescribeId.Create("original-regular-height"), DeclarationHandle.Create(Owner + "original_regular_height"),
                H("All actual antipodes have one positive height"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For every complete three-ball chart a of D(p), and every full original confirmer ep of p, there exists one real sigma>0 with the following property. For every unit direction v, every original pure q=a(v), every complete three-ball chart b of D(q), every unit s with b(s)=p, every original pure endpoint aa=b(-s), and every original full confirmer ea of aa, the height (u-ep)(aa) is at least sigma. The endpoint belongs to the entire D(q), and every original mixed state x in D(q) has (u-ep)(x)<=(u-ep)(aa). Thus the same endpoint attains the maximum over the complete adjacent ball. Sigma is chosen before the direction, second chart, endpoint and confirming effect.")),
                    Paragraph(Text("Write N for the whole cone of original positive functionals vanishing at p, L for its actual linear span, and g=u-ep. OriginalNormalRestriction.original_normal_restriction identifies the actual restriction L to the affine functions on the whole first ball as a linear isomorphism, and places g in the interior of N relative to L. Inverting this restriction on linear coordinate functions gives a linear direction map v to H(v), with H(v)(a(w))=inner(v,w). A neighborhood of g in N and the operator norm of this direction map give one finite M>=1 such that abs(H(v)(x))<=M g(x) for every unit v and every x in the entire original cone.")),
                    Paragraph(Text("WholePairBallConfirmation.affine_zero_antipode applied to the complement of any effect peaking at a(v) gives its first-ball restriction as 1-lam+lam inner(v,w). Every full confirmer e of q vanishes at p, so it belongs to the original L. Restriction injectivity therefore lifts the formula to the whole V as e=g+lam(H(v)-g). Choose one y in the complete D(q) different from p. The exact original one-face of ep implies g(y)>0. All full confirmers of q vanish at this same y; evaluating the lifted formula fixes lam uniquely. Nonemptiness of the full confirming fiber now makes q a singleton-confirmation label. Moreover the same equation and the whole-cone bound give lam>=1/(1+M), uniformly over all directions and every full confirmer.")),
                    Paragraph(Text("Only after proving singleton confirmation at q do we use the actual restriction isomorphism on the second ball. Set t=ep(aa) and d=ea(p), keeping the same arbitrary ea throughout. The two antipodal peak formulas on b give (1-d)ep+(1-t)ea=(1-d t)(u-eq) on the whole second ball, where eq is the unique full confirmer of q. All three functionals are positive and vanish at q, hence belong to its original normal span; the now justified second restriction injectivity makes this an identity on all of V. The original singleton one-face gives t<1, and properness gives t>=0 and d<=1.")),
                    Paragraph(Text("At the different point a(-v) in the first ball, ep is zero and (u-eq)(a(-v))=2 lam. The whole-space identity therefore gives ea(a(-v))>=2 lam>=2/(1+M)>0. This single positive reading is uniform over all directions, all complete second charts and all actual endpoint confirmers. Applying RegularAnchorHeight.regular_anchor_uniform_height with epsilon=2/(1+M) gives one sigma. Finally affine_zero_antipode for g on the entire second ball shows that its opposite endpoint aa attains its maximum, including every mixed state. The construction never identifies aa with a(-v).")),
                    Paragraph(Text("The constant belongs to one fixed original regular anchor and its first chart. The conclusion supplies no uniform constant over all pure labels and no regularity of q or aa. The finite bound is obtained at p; no uniform reverse directional scale or uniform gap in 1-d is inserted. No complete support-function construction, directional Lipschitz statement, physical realization, or empirical assertion is included."))), DescribeRole.Theorem))));
}
